 14px;background:#f2f3ed;color:@color-danger;font-size:13px}.creation aside{min-height:0;padding:22px;background:#f7f8f3;overflow:auto}.creation aside>header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.creation aside h2{font-size:19px;font-weight:800}.creation aside header span,.creation aside>small{font-size:11px;color:@color-text-secondary}.creation aside header strong{display:grid;place-items:center;min-width:54px;height:30px;padding:0 8px;border:1px solid @color-border-strong;border-radius:@radius-sm;background:@color-primary;color:@color-text;font-size:13px;box-shadow:2px 2px 0 @color-border-strong}.working-document{border:1px solid @color-border-strong;border-radius:@radius-md;padding:13px 14px;margin-bottom:14px;background:#fff}.working-document h3{font-size:12px;font-weight:800}.working-document pre{max-height:210px;overflow:auto;white-space:pre-wrap;font:11px/1.7 ui-monospace,SFMono-Regular,Menlo,monospace;color:#50534b;margin-top:8px}.creation dl{border-top:1px solid @color-border-strong}.creation dl div{display:grid;grid-template-columns:92px minmax(0,1fr);gap:12px;padding:10px 0;border-bottom:1px solid @color-border}.creation dt{font-size:10px;font-weight:700;color:@color-text-secondary;text-transform:uppercase}.creation dd{font-size:12px;line-height:1.55;white-space:pre-wrap}.creation dd.missing{color:#8d9086}.creation aside>button{width:100%;margin-top:18px}.creation aside>small{display:block;text-align:center;margin-top:9px}@media(max-width:900px){.creation>header{grid-template-columns:1fr auto;gap:12px}.creation>header>button:first-child{grid-column:1/-1}.creation>header h1{font-size:29px}.creation__layout{grid-template-columns:1fr;height:auto;max-height:none;box-shadow:4px 4px 0 #d6d8cf}.creation main{min-height:640px;border-right:0}.creation aside{border-top:1px solid @color-border-strong}.messages{min-height:420px}}@media(max-width:560px){.creation>header{display:flex;flex-wrap:wrap}.creation>header>div{order:3;width:100%}.manual{margin-left:auto}.creation>header h1{font-size:27px}.creation__layout{box-shadow:none}.creation main{min-height:600px}.agent{padding:0 14px}.agent label{display:flex;align-items:center}.agent select{max-width:210px}.messages{padding:17px;min-height:380px}.creation form{grid-template-columns:1fr;padding:13px}.creation form button{height:42px}.creation aside{padding:18px}.creation dl div{grid-template-columns:78px minmax(0,1fr)}}
</style>
